gq 3;
query recent_within($q: Vector(3), $r: F64) {
  match {
    from distance(
      { match { $d: Doc  $d.year >= 2025 } return { $d } },
      $d.embedding, $q
    )
    $distance <= $r
  }
  return { $d.title, $distance }
  order { $distance }
  limit 10
}
